  ],
  "claims": [
    {"key": "c1", "text": "Первые теории упругого режима появились в 30-х годах 20-го века. Их авторы: Маскет, Шилсуиз, Херст, Тсейс и Джекоб.", "kind": "observation", "unit_id": "u-475-052a3f", "page": 475, "quote": "Первыми исследователями, разрабатывавшими теорию упругого режима в 30-х годах 20-го века, были Маскет, Шилсуиз, Херст, Тсейс и Джекоб.", "numbers": ["30", "20"], "question": null},
    {"key": "c2", "text": "Ранние авторы не учитывали объёмную упругость пласта.", "kind": "observation", "unit_id": "u-475-052a3f", "page": 475, "quote": "Однако они не учитывали объемную упругость пласта.", "numbers": [], "question": null},
    {"key": "c3", "text": "Наиболее полную теорию упругого режима разработал В.Н.Щелкачев. Он учёл упругие свойства твёрдого скелета пласта и насыщающих жидкостей.", "kind": "observation", "unit_id": "u-475-052a3f", "page": 475, "quote": "Наиболее полно теория упругого режима с учетом упругих свойств твердого скелета пласта и насыщающих жидкостей была разработана В.Н.Щелкачевым.", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Упругий режим — это приток жидкости за счёт упругих сил пласта и жидкости. Чтобы описать его полностью, нужно учитывать упругость и пласта, и жидкости.", "claims": ["c3"], "hypothesis": false},
    {"text": "Ранние модели учитывали не весь этот набор упругих свойств. Они не включали объёмную упругость пласта, поэтому их описание было неполным.", "claims": ["c2"], "hypothesis": false},
    {"text": "Щелкачев добавил в теорию упругость твёрдого скелета пласта и насыщающих жидкостей. Это сделало описание упругого режима наиболее полным из известных в тексте.", "claims": ["c3"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалисту полезно проверять, какая теория лежит в основе расчёта. Важно, учитывает ли она упругость пласта и жидкости.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
